fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Initialize the output matrices with capacity for efficiency.
    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &y_val in &y {
        // Clone x for the current row in x_grid
        let row_x = x.clone(); 
        
        // Create a row for y_grid filled with the current y value repeated `cols` times
        let row_y = vec![y_val; cols];

        x_grid.push(row_x);
        y_grid.push(row_y);
    }

    (x_grid, y_grid)
}